function selectRenderedNote(note, extendRange = false) {
  $('score').querySelectorAll('.acorde-selected').forEach((item) => item.classList.remove('acorde-selected'));
  note.classList.add('acorde-selected');
  note.focus({ preventScroll: true });
  const address = ['part', 'staff', 'measure', 'voice', 'note'].reduce((value, key) => ({ ...value, [key]: Number(note.dataset[key]) }), {});
  if (extendRange && selectedAddress && selectedAddress.part === address.part && selectedAddress.staff === address.staff) {
    selectedRange = [Math.min(selectedAddress.measure, address.measure), Math.max(selectedAddress.measure, address.measure)];
    $('score').querySelectorAll('[data-acorde-kind="measure"]').forEach((measure) => measure.classList.toggle('acorde-range', Number(measure.dataset.measure) >= selectedRange[0] && Number(measure.dataset.measure) <= selectedRange[1]));
  } else if (!extendRange) selectedRange = null;
  selectedAddress = address;
  activeVoiceIndex = address.voice;
  const voiceSelector = $('voice-select');
  if (voiceSelector) { refreshVoiceSelector(); voiceSelector.value = String(activeVoiceIndex); }
  const staffSelector = $('staff-select');
  if (staffSelector) { staffSelector.value = String(address.staff); }
  const item = currentScore?.parts?.[address.part]?.staves?.[address.staff]?.measures?.[address.measure]?.voices?.[address.voice]?.[address.note];
  if (item) { $('duration-select').value = String(item.duration || 'quarter').toLowerCase(); $('dot-toggle').checked = Number(item.dot_count || 0) > 0; $('tuplet-select').value = item.tuplet ? `${item.tuplet.actual_notes}:${item.tuplet.normal_notes}` : ''; $('dynamic-select').value = item.dynamic || ''; $('grace-select').value = item.is_grace ? (item.grace_slash ? 'acciaccatura' : 'appoggiatura') : ''; }
  selectionPlayButton.disabled = !selectedRange;
  selectionPlayButton.title = selectedRange ? `Play measures ${selectedRange[0] + 1}–${selectedRange[1] + 1}` : 'Select a measure range first';
}
