$('rehearsal-button').addEventListener('click', async () => { if (!currentScore || !selectedAddress) return; const measure = selectedAddress.measure; const current = currentScore.parts?.[selectedAddress.part]?.staves?.[selectedAddress.staff]?.measures?.[measure]?.rehearsal || ''; const text = window.prompt(`Rehearsal mark for measure ${measure + 1}`, current); if (text === null) return; try { await applyCommand({ type: 'set_rehearsal_mark', measure_index: measure, text: text.trim() || null }, 'SetRehearsalMark'); } catch (error) { alert(`リハーサルマークを変更できませんでした: ${error.message}`); } });
$('measure-tempo-button').addEventListener('click', async () => { if (!currentScore || !selectedAddress) return; const measure = selectedAddress.measure; const current = currentScore.parts?.[selectedAddress.part]?.staves?.[selectedAddress.staff]?.measures?.[measure]?.tempo || ''; const value = window.prompt(`Tempo BPM for measure ${measure + 1} (blank clears override)`, current ? String(current) : ''); if (value === null) return; const bpm = value.trim() ? Number(value) : null; if (bpm !== null && (!Number.isInteger(bpm) || bpm < 1 || bpm > 400)) return alert('テンポは1〜400の整数で入力してください。'); try { await applyCommand({ type: 'set_tempo_at_measure', measure_index: measure, bpm }, 'SetTempoAtMeasure'); } catch (error) { alert(`小節テンポを変更できませんでした: ${error.message}`); } });
