function installRepeatControls() { const start = document.createElement('button'); start.id = 'repeat-start-button'; start.className = 'quiet'; start.textContent = 'Repeat Start'; const end = document.createElement('button'); end.id = 'repeat-end-button'; end.className = 'quiet'; end.textContent = 'Repeat End'; $('score-meta').insertBefore(start, $('mixer-button')); $('score-meta').insertBefore(end, $('mixer-button')); const apply = async (side, barline) => { if (!currentScore || !selectedAddress) return; const measure = currentScore.parts?.[selectedAddress.part]?.staves?.[selectedAddress.staff]?.measures?.[selectedAddress.measure]; const current = side === 'left' ? measure?.barline_left : measure?.barline_right; const next = current === barline ? 'Normal' : barline; try { await applyCommand({ type: 'set_barline', measure_index: selectedAddress.measure, side, barline: next }, next === 'Normal' ? 'ClearBarline' : 'SetBarline'); } catch (error) { alert(`反復記号を変更できませんでした: ${error.message}`); } }; start.addEventListener('click', () => apply('left', 'RepeatStart')); end.addEventListener('click', () => apply('right', 'RepeatEnd')); }
