function installNavigationControls() { const navigation = document.createElement('button'); navigation.id = 'navigation-button'; navigation.className = 'quiet'; navigation.textContent = 'Navigation'; const volta = document.createElement('button'); volta.id = 'volta-button'; volta.className = 'quiet'; volta.textContent = 'Volta'; $('score-meta').insertBefore(navigation, $('mixer-button')); $('score-meta').insertBefore(volta, $('mixer-button')); navigation.addEventListener('click', async () => { if (!currentScore || !selectedAddress) return; const measure = selectedAddress.measure; const current = currentScore.parts?.[selectedAddress.part]?.staves?.[selectedAddress.staff]?.measures?.[measure]?.navigation || ''; const value = window.prompt('Navigation mark (Segno, Coda, Fine, DaCapo...)', current); if (value === null) return; const allowed = ['Segno', 'Coda', 'Fine', 'DaCapo', 'DaCapoAlFine', 'DaCapoAlCoda', 'DalSegno', 'DalSegnoAlFine', 'DalSegnoAlCoda', 'ToCoda']; if (value.trim() && !allowed.includes(value.trim())) return alert(`Navigation markは ${allowed.join(', ')} のいずれかです。`); try { await applyCommand({ type: 'set_navigation_mark', measure_index: measure, mark: value.trim() || null }, 'SetNavigationMark'); } catch (error) { alert(`ナビゲーション記号を変更できませんでした: ${error.message}`); } }); volta.addEventListener('click', async () => { if (!currentScore || !selectedAddress) return; const measure = selectedAddress.measure; const current = currentScore.parts?.[selectedAddress.part]?.staves?.[selectedAddress.staff]?.measures?.[measure]?.volta; const value = window.prompt('Volta ending number (blank clears, e.g. 1 or 2)', current?.number ? String(current.number) : ''); if (value === null) return; const number = value.trim() ? Number(value) : null; if (number !== null && (!Number.isInteger(number) || number < 1 || number > 8)) return alert('Volta numberは1〜8の整数で入力してください。'); try { await applyCommand({ type: 'set_volta', measure_index: measure, volta: number === null ? null : { number, kind: 'begin_end' } }, 'SetVolta'); } catch (error) { alert(`Voltaを変更できませんでした: ${error.message}`); } }); }
installNavigationControls();
function installExpressionControls() { const expression = document.createElement('button'); expression.id = 'expression-button'; expression.className = 'quiet'; expression.textContent = 'Expression'; const cue = document.createElement('button'); cue.id = 'cue-button'; cue.className = 'quiet'; cue.textContent = 'Cue'; $('score-meta').insertBefore(expression, $('mixer-button')); $('score-meta').insertBefore(cue, $('mixer-button')); expression.addEventListener('click', async () => { if (!currentScore || !selectedAddress) return; const measure = selectedAddress.measure; const current = currentScore.parts?.[selectedAddress.part]?.staves?.[selectedAddress.staff]?.measures?.[measure]?.expression_text || ''; const text = window.prompt(`Expression for measure ${measure + 1}`, current); if (text === null) return; try { await applyCommand({ type: 'set_expression_text', measure_index: measure, text: text.trim() || null }, 'SetExpressionText'); } catch (error) { alert(`表現記号を変更できませんでした: ${error.message}`); } }); cue.addEventListener('click', async () => { if (!currentScore || !selectedAddress) return; const { part, staff, measure, voice, note } = selectedAddress; const item = currentScore.parts?.[part]?.staves?.[staff]?.measures?.[measure]?.voices?.[voice]?.[note]; if (!item) return; try { await applyCommand({ type: 'set_cue', part_index: part, staff_index: staff, measure_index: measure, voice, note_index: note, is_cue: !item.is_cue }, 'SetCue'); } catch (error) { alert(`キュー音符を変更できませんでした: ${error.message}`); } }); }
installExpressionControls();
function installNoteAppearanceControls() { const head = document.createElement('button'); head.id = 'note-head-button'; head.className = 'quiet'; head.textContent = 'Notehead'; const fingering = document.createElement('button'); fingering.id = 'fingering-button'; fingering.className = 'quiet'; fingering.textContent = 'Fingering'; $('score-meta').insertBefore(head, $('mixer-button')); $('score-meta').insertBefore(fingering, $('mixer-button')); head.addEventListener('click', async () => { if (!currentScore || !selectedAddress) return; const { part, staff, measure, voice, note } = selectedAddress; const value = window.prompt('Notehead: Normal, Diamond, X, Triangle', 'Normal'); if (value === null) return; const normalized = value.trim().toLowerCase(); const noteHead = normalized === 'diamond' ? 'Diamond' : normalized === 'x' ? 'X' : normalized === 'triangle' ? 'Triangle' : normalized === 'normal' ? 'Normal' : null; if (!noteHead) return alert('Noteheadは Normal / Diamond / X / Triangle のいずれかです。'); try { await applyCommand({ type: 'set_note_head', part_index: part, staff_index: staff, measure_index: measure, voice, note_index: note, note_head: noteHead }, 'SetNoteHead'); } catch (error) { alert(`符頭を変更できませんでした: ${error.message}`); } }); fingering.addEventListener('click', async () => { if (!currentScore || !selectedAddress) return; const { part, staff, measure, voice, note } = selectedAddress; const item = currentScore.parts?.[part]?.staves?.[staff]?.measures?.[measure]?.voices?.[voice]?.[note]; const value = window.prompt('Fingering: blank clears, 0-5', item?.fingering == null ? '' : String(item.fingering)); if (value === null) return; const fingeringValue = value.trim() ? Number(value) : null; if (fingeringValue !== null && (!Number.isInteger(fingeringValue) || fingeringValue < 0 || fingeringValue > 5)) return alert('Fingeringは0〜5の整数です。'); try { await applyCommand({ type: 'set_fingering', part_index: part, staff_index: staff, measure_index: measure, voice, note_index: note, fingering: fingeringValue }, 'SetFingering'); } catch (error) { alert(`運指を変更できませんでした: ${error.message}`); } }); }
installNoteAppearanceControls();
