function installOrnamentControls() { const arpeggio = document.createElement('button'); arpeggio.id = 'arpeggio-button'; arpeggio.className = 'quiet'; arpeggio.textContent = 'Arpeggio'; const trill = document.createElement('button'); trill.id = 'trill-button'; trill.className = 'quiet'; trill.textContent = 'Trill line'; $('score-meta').insertBefore(arpeggio, $('mixer-button')); $('score-meta').insertBefore(trill, $('mixer-button')); arpeggio.addEventListener('click', async () => { if (!currentScore || !selectedAddress) return; const { part, staff, measure, voice, note } = selectedAddress; const value = window.prompt('Arpeggio: up, down, or blank to clear', 'up'); if (value === null) return; const direction = value.trim() ? value.trim().toLowerCase() === 'up' ? true : value.trim().toLowerCase() === 'down' ? false : undefined : null; if (direction === undefined) return alert('Arpeggioは up / down のいずれかです。'); try { await applyCommand({ type: 'set_arpeggio', part_index: part, staff_index: staff, measure_index: measure, voice_index: voice, note_index: note, direction }, 'SetArpeggio'); } catch (error) { alert(`アルペジオを変更できませんでした: ${error.message}`); } }); let start = null; trill.addEventListener('click', () => { start = selectedAddress; if (start) alert('Trill line: 終了音符をクリックしてください。'); }); window.addEventListener('score-note-click', async (event) => { if (!start || !event.detail || !currentScore) return; const end = event.detail; try { await applyCommand({ type: 'toggle_trill_line', start, end }, 'ToggleTrillLine'); } catch (error) { alert(`トリルラインを変更できませんでした: ${error.message}`); } finally { start = null; } }); }
