function installStemControl() { const button = document.createElement('button'); button.id = 'stem-button'; button.className = 'quiet'; button.textContent = 'Stem'; $('score-meta').insertBefore(button, $('mixer-button')); button.addEventListener('click', async () => { if (!currentScore || !selectedAddress) return; const { part, staff, measure, voice, note } = selectedAddress; const item = currentScore.parts?.[part]?.staves?.[staff]?.measures?.[measure]?.voices?.[voice]?.[note]; const value = window.prompt('Stem direction: auto, up, or down', item?.stem_up === true ? 'up' : item?.stem_up === false ? 'down' : 'auto'); if (value === null) return; const stemUp = value.trim().toLowerCase() === 'auto' ? null : value.trim().toLowerCase() === 'up' ? true : value.trim().toLowerCase() === 'down' ? false : undefined; if (stemUp === undefined) return alert('Stem directionは auto / up / down のいずれかです。'); try { await applyCommand({ type: 'set_stem', part_index: part, staff_index: staff, measure_index: measure, voice_index: voice, note_index: note, stem_up: stemUp }, 'SetStem'); } catch (error) { alert(`stem方向を変更できませんでした: ${error.message}`); } }); }
