function installLayoutControls() { const multiRest = document.createElement('button'); multiRest.id = 'multi-rest-button'; multiRest.className = 'quiet'; multiRest.textContent = 'Multi-rest'; const pageBreak = document.createElement('button'); pageBreak.id = 'page-break-button'; pageBreak.className = 'quiet'; pageBreak.textContent = 'Page break'; const systemBreak = document.createElement('button'); systemBreak.id = 'system-break-button'; systemBreak.className = 'quiet'; systemBreak.textContent = 'System break'; $('score-meta').insertBefore(multiRest, $('mixer-button')); $('score-meta').insertBefore(pageBreak, $('mixer-button')); $('score-meta').insertBefore(systemBreak, $('mixer-button')); const measureAtSelection = () => selectedAddress?.measure; multiRest.addEventListener('click', async () => { const measure = measureAtSelection(); if (!currentScore || measure === undefined) return; const current = currentScore.parts?.[0]?.staves?.[0]?.measures?.[measure]?.multi_rest_count; const value = window.prompt('Multi-rest count (blank clears, 2-99)', current ? String(current) : ''); if (value === null) return; const count = value.trim() ? Number(value) : null; if (count !== null && (!Number.isInteger(count) || count < 2 || count > 99)) return alert('Multi-rest countは2〜99の整数です。'); try { await applyCommand({ type: 'set_multi_rest', measure_index: measure, count }, 'SetMultiRest'); } catch (error) { alert(`マルチレストを変更できませんでした: ${error.message}`); } }); const toggleBreak = (type, button) => async () => { const measure = measureAtSelection(); if (!currentScore || measure === undefined) return; const current = currentScore.parts?.[0]?.staves?.[0]?.measures?.[measure]?.[type]; try { await applyCommand({ type: type === 'page_break' ? 'set_page_break' : 'set_system_break', measure_index: measure, value: !current }, type === 'page_break' ? 'SetPageBreak' : 'SetSystemBreak'); button.classList.toggle('active', !current); } catch (error) { alert(`レイアウト区切りを変更できませんでした: ${error.message}`); } }; pageBreak.addEventListener('click', toggleBreak('page_break', pageBreak)); systemBreak.addEventListener('click', toggleBreak('system_break', systemBreak)); }
installLayoutControls();
function installMidiInputControl() { const button = document.createElement('button'); button.id = 'midi-input-button'; button.className = 'quiet'; button.textContent = 'MIDI input'; const status = document.createElement('span'); status.id = 'midi-input-status'; status.className = 'muted'; status.textContent = 'MIDI off'; $('score-meta').insertBefore(button, $('mixer-button')); $('score-meta').insertBefore(status, $('mixer-button')); const handleMessage = async ({ data }) => { const [command, midi, velocity] = data || []; if ((command & 0xf0) !== 0x90 || !velocity || !currentScore) return; const part = currentScore.parts?.[activePartIndex]; const staff = part?.staves?.[Number($('staff-select')?.value || 0)]; const measureIndex = selectedAddress?.measure ?? 0; const voiceIndex = selectedAddress?.voice ?? activeVoiceIndex; const voice = staff?.measures?.[measureIndex]?.voices?.[voiceIndex]; if (!voice) return; try { await applyCommand({ type: 'add_note', part_index: activePartIndex, staff_index: Number($('staff-select')?.value || 0), measure_index: measureIndex, voice: voiceIndex, position: voice.length, pitch: pitchFromMidi(midi), duration: 'quarter', dot_count: 0, is_rest: false }, 'MidiInputNote'); } catch (error) { status.textContent = `MIDI error: ${error.message}`; } }; button.addEventListener('click', async () => { if (!navigator.requestMIDIAccess) { status.textContent = 'Web MIDI unavailable'; return; } try { const access = await navigator.requestMIDIAccess(); const input = [...access.inputs.values()][0]; if (!input) { status.textContent = 'No MIDI input'; return; } if (midiInput) midiInput.onmidimessage = null; midiInput = input; midiInput.onmidimessage = handleMessage; status.textContent = `MIDI: ${input.name || 'connected'}`; } catch (error) { status.textContent = `MIDI denied: ${error.message}`; } }); }
installMidiInputControl();
